import React, { useState, useEffect, useContext, useCallback } from 'react';
import { UserPlus, Search, Edit2, Trash2, Filter } from 'lucide-react';
import { getUsers, createUser, updateUser, deleteUser } from '../../services/userService';
import EmployeeFormModal from '../../components/employees/EmployeeFormModal';
import Badge from '../../components/common/Badge';
import Pagination from '../../components/common/Pagination';
import LoadingSpinner from '../../components/common/LoadingSpinner';
import { NotificationContext } from '../../context/NotificationContext';

const departments = [
  'All Departments',
  'Editorial',
  'Content Writing',
  'Proofreading',
  'Graphic Design',
  'Marketing',
  'Sales',
  'Printing',
  'Warehouse',
  'Accounts',
  'HR',
  'IT',
];

const EmployeesPage = () => {
  const { addToast } = useContext(NotificationContext);
  const [employees, setEmployees] = useState([]);
  const [loading, setLoading] = useState(true);
  const [total, setTotal] = useState(0);
  const [pages, setPages] = useState(1);
  const [currentPage, setCurrentPage] = useState(1);

  // Filters
  const [search, setSearch] = useState('');
  const [department, setDepartment] = useState('');
  const [salaryType, setSalaryType] = useState('');
  const [status, setStatus] = useState('');

  // Modals
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedEmp, setSelectedEmp] = useState(null);

  const fetchEmployees = useCallback(async () => {
    setLoading(true);
    try {
      const res = await getUsers({
        page: currentPage,
        search,
        department: department === 'All Departments' ? '' : department,
        salaryType,
        status,
        limit: 10,
      });
      setEmployees(res.data);
      setTotal(res.total);
      setPages(res.pages);
    } catch (err) {
      addToast('Failed to fetch employees', 'danger');
    } finally {
      setLoading(false);
    }
  }, [currentPage, search, department, salaryType, status, addToast]);

  useEffect(() => {
    fetchEmployees();
  }, [fetchEmployees]);

  const handleOpenAddModal = () => {
    setSelectedEmp(null);
    setIsModalOpen(true);
  };

  const handleOpenEditModal = (emp) => {
    setSelectedEmp(emp);
    setIsModalOpen(true);
  };

  const handleFormSubmit = async (formData) => {
    try {
      if (selectedEmp) {
        await updateUser(selectedEmp._id, formData);
        addToast('Employee updated successfully', 'success');
      } else {
        await createUser(formData);
        addToast('Employee added successfully', 'success');
      }
      setIsModalOpen(false);
      fetchEmployees();
    } catch (err) {
      addToast(err.response?.data?.message || 'Operation failed', 'danger');
    }
  };

  const handleDelete = async (id, name) => {
    if (window.confirm(`Are you sure you want to remove employee '${name}'?`)) {
      try {
        await deleteUser(id);
        addToast('Employee deleted successfully', 'success');
        fetchEmployees();
      } catch (err) {
        addToast(err.response?.data?.message || 'Delete failed', 'danger');
      }
    }
  };

  return (
    <div className="page-container">
      <div className="page-header">
        <div>
          <h1 className="page-title">Employee Directory</h1>
          <p className="page-subtitle">Manage Pustak Market publication staff, roles, & salary models</p>
        </div>
        <button className="btn btn-primary" onClick={handleOpenAddModal}>
          <UserPlus size={18} /> Add New Employee
        </button>
      </div>

      {/* Filter & Search Bar */}
      <div className="search-filter-panel">
        <div className="search-input-wrapper">
          <Search className="search-icon" size={18} />
          <input
            type="text"
            className="form-input"
            placeholder="Search by ID, Name, Email, or Designation..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </div>

        <div className="flex-row" style={{ gap: '10px', flexWrap: 'wrap' }}>
          <div className="flex-row" style={{ gap: '6px' }}>
            <Filter size={16} color="var(--text-muted)" />
            <select
              className="form-select"
              value={department}
              onChange={(e) => setDepartment(e.target.value)}
              style={{ minWidth: '150px' }}
            >
              {departments.map((d) => (
                <option key={d} value={d === 'All Departments' ? '' : d}>
                  {d}
                </option>
              ))}
            </select>
          </div>

          <select
            className="form-select"
            value={salaryType}
            onChange={(e) => setSalaryType(e.target.value)}
            style={{ minWidth: '140px' }}
          >
            <option value="">All Salary Models</option>
            <option value="Monthly">Monthly Fixed</option>
            <option value="Task Based">Per Task</option>
            <option value="Hybrid">Hybrid</option>
          </select>

          <select
            className="form-select"
            value={status}
            onChange={(e) => setStatus(e.target.value)}
            style={{ minWidth: '120px' }}
          >
            <option value="">All Statuses</option>
            <option value="Active">Active</option>
            <option value="Inactive">Inactive</option>
            <option value="On Leave">On Leave</option>
            <option value="Terminated">Terminated</option>
          </select>
        </div>
      </div>

      {/* Data Table */}
      {loading ? (
        <LoadingSpinner />
      ) : (
        <div className="table-container">
          <table className="data-table">
            <thead>
              <tr>
                <th>Employee ID</th>
                <th>Employee</th>
                <th>Department</th>
                <th>Designation</th>
                <th>Salary Model</th>
                <th>Compensation</th>
                <th>Status</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {employees.length === 0 ? (
                <tr>
                  <td colSpan="8" style={{ textAlign: 'center', padding: '30px', color: 'var(--text-muted)' }}>
                    No employees found matching criteria.
                  </td>
                </tr>
              ) : (
                employees.map((emp) => (
                  <tr key={emp._id}>
                    <td>
                      <strong style={{ color: 'var(--primary)' }}>{emp.employeeId}</strong>
                    </td>
                    <td>
                      <div className="flex-row">
                        {emp.profileImage ? (
                          <img src={emp.profileImage} alt="" className="avatar" />
                        ) : (
                          <div className="avatar-placeholder">
                            {emp.fullName.charAt(0).toUpperCase()}
                          </div>
                        )}
                        <div>
                          <div style={{ fontWeight: 700 }}>{emp.fullName}</div>
                          <div style={{ fontSize: '0.75rem', color: 'var(--text-muted)' }}>{emp.email}</div>
                        </div>
                      </div>
                    </td>
                    <td>{emp.department}</td>
                    <td>{emp.designation}</td>
                    <td>
                      <Badge text={emp.salaryType} />
                    </td>
                    <td>
                      {emp.salaryType === 'Monthly' && `₹${(emp.fixedSalary || 0).toLocaleString('en-IN')}/mo`}
                      {emp.salaryType === 'Task Based' && `₹${(emp.perTaskRate || 0).toLocaleString('en-IN')}/task`}
                      {emp.salaryType === 'Hybrid' && `₹${(emp.fixedSalary || 0).toLocaleString('en-IN')} + ₹${(emp.perTaskRate || 0).toLocaleString('en-IN')}/task`}
                    </td>
                    <td>
                      <Badge text={emp.status} />
                    </td>
                    <td>
                      <div className="flex-row" style={{ gap: '8px' }}>
                        <button
                          className="btn btn-secondary btn-sm"
                          onClick={() => handleOpenEditModal(emp)}
                          title="Edit Employee"
                        >
                          <Edit2 size={14} />
                        </button>
                        <button
                          className="btn btn-danger btn-sm"
                          onClick={() => handleDelete(emp._id, emp.fullName)}
                          title="Delete Employee"
                        >
                          <Trash2 size={14} />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      )}

      <Pagination currentPage={currentPage} totalPages={pages} onPageChange={(p) => setCurrentPage(p)} />

      {/* Add / Edit Form Modal */}
      <EmployeeFormModal
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onSubmit={handleFormSubmit}
        initialData={selectedEmp}
        isEdit={!!selectedEmp}
      />
    </div>
  );
};

export default EmployeesPage;
